import Foundation
import Darwin
import ThermoKit
guard getuid() != 0 else { exit(2) }
let smc = try SMC()
var rows: [[String: Any]] = []
for name in ["CH0B", "CH0C", "CHTE"] {
    let key = FourCC(name)
    do {
        let info = try smc.info(key)
        let value = try smc.read(key)
        rows.append(["key": name, "type": info.type.description, "size": info.size, "attributes": info.attributes, "hex": value.hex])
    } catch { rows.append(["key": name, "error": String(describing: error)]) }
}
print(String(decoding: try JSONSerialization.data(withJSONObject: rows, options: [.prettyPrinted, .sortedKeys]), as: UTF8.self))
